"""Freeze an unpublished UI candidate; this is not visual acceptance/publication."""
from pathlib import Path
import hashlib,json,datetime
R=Path(__file__).resolve().parents[1]
H=lambda b:hashlib.sha256(b).hexdigest()
paths=[R/'web/index.html']+[p for folder in ['web/src','web/public'] for p in (R/folder).rglob('*') if p.is_file()]
rows=sorted([{'path':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'sha256':H(p.read_bytes())}for p in paths],key=lambda x:x['path'])
aggregate=json.loads((R/'tests/v17/aggregate-result.json').read_text());assert aggregate.get('status')=='PASS' and aggregate.get('npm_test_exit')==0 and aggregate.get('runtime_test_inputs_unchanged') is True,'Final aggregate not accepted'
for rel,expected in json.loads((R/'tests/v17/test-start-hashes.json').read_text()).items():assert H((R/rel).read_bytes())==expected,'Source changed after aggregate: '+rel
for rel in ['tests/v17/reference-ui-controller.log','tests/v17/standalone-audit.log','tests/v17/payload-audit.log','tests/v17/css-parse.log']:assert 'PASS' in (R/rel).read_text(),'Missing passing log: '+rel
anchors={p:{'bytes':(R/p).stat().st_size,'sha256':H((R/p).read_bytes())}for p in ['dist/malabar-hot-coast.html','dist/game.bundle.js','web/package.json','web/package-lock.json','web/build-standalone.mjs','web/build-ui-preview.mjs','tests/v17/npm-test-frozen.log','tests/v17/aggregate-result.json','tests/v17/reference-ui-controller.log','tests/v17/preservation-report.json','tests/v17/standalone-audit.log','tests/v17/payload-audit.log','tests/v17/css-parse.log','tests/v17/test-start-hashes.json','tests/v17/r3-local-preview-blocker.json','tools/scene-proof-r3/menu-isolation-results.json','tools/scene-proof-r3/menu-projection.log','tools/scene-proof-r3/proof-final-corrected/receipt.json','design-qa.md']}
manifest={'candidate':'MALABAR V17 UI CANDIDATE R3','status':'UNPUBLISHED — R3 isolated layout and original-scene revision; full WebGL scene fidelity and native FPS NOT accepted','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'runtime_tree_sha256':H(''.join(x['path']+'\0'+x['sha256']+'\n'for x in rows).encode()),'runtime_files':rows,'anchors':anchors,'protected_scope':'All138 V16 protected files exact; only index, style, main and scene changed from143-file liveV16.1 runtime, plus two original menu-scene modules','private_references_included':False,'blocking_gate':'See design-qa.md for current CSS evidence. Actual 3D game rendering, native performance and parent approval still required before publishing; no hosting changes authorized.','known_visual_gap':'Original transparent car thumbnails are not photoreal scenic reference matches. Blender proof, if included, is an offline visualization of original geometry/material intent, not actual WebGL evidence.'}
(R/'tests/v17/CANDIDATE_MANIFEST.json').write_text(json.dumps(manifest,indent=2)+'\n')
(R/'FULL_BACKUP_MANIFEST.json').write_text(json.dumps({'kind':'Source-root pointer (not an archive manifest)','candidate':manifest['candidate'],'authoritative_candidate_manifest':'tests/v17/CANDIDATE_MANIFEST.json','runtime_tree_sha256':manifest['runtime_tree_sha256'],'historical_manifest':'docs/provenance/INHERITED_V12_BACKUP_MANIFEST.json','note':'The full ZIP has its own generated complete-file FULL_BACKUP_MANIFEST.json. This pointer replaces misleading inherited V12 metadata.'},indent=2)+'\n')
print(json.dumps({k:manifest[k]for k in ['candidate','status','runtime_tree_sha256']},indent=2));print('Runtime files',len(rows))
